type ExtraModel = Pick<ModelSpec, "id" | "name" | "family" | "task" | "sklearn"> & Partial<Omit<ModelSpec, "id" | "name" | "family" | "task" | "sklearn">>;

const makeExtraModel = (model: ExtraModel): ModelSpec => {
  const profile = familyProfiles[model.family];
  return {
    ...model,
    summary: model.summary ?? modelSummaries[model.id] ?? `${model.name} is a ${model.family.toLowerCase()} estimator for ${model.task.toLowerCase()}.`,
    when: model.when ?? profile?.when ?? "Use it when its assumptions match the shape of your data.",
    why: model.why ?? profile?.why ?? "It offers a distinct bias, variance, or compute trade-off worth testing.",
    avoid: model.avoid ?? profile?.avoid ?? "The data violates its core assumptions or the compute cost does not fit.",
    scaling: model.scaling ?? profile?.scaling ?? "Check the estimator docs; scale when distances or regularization compare magnitudes.",
    interpretability: model.interpretability ?? profile?.interpretability ?? "Medium; inspect learned parameters and validate explanations.",
    training: model.training ?? profile?.training ?? "Usually fast to medium on ordinary tabular data.",
    prediction: model.prediction ?? profile?.prediction ?? "Usually fast to medium depending on the learned components.",
    probability: model.probability ?? profile?.probability ?? "Depends on the estimator; check whether predict_proba is available.",
    strengths: model.strengths ?? profile?.strengths ?? ["Useful baseline", "Clear sklearn implementation", "Distinct modeling assumption"],
    limitations: model.limitations ?? profile?.limitations ?? ["Sensitive to assumptions", "Needs validation", "Can underfit or overfit outside its sweet spot"],
    parameters: model.parameters ?? profile?.parameters ?? [{ name: "main hyperparameters", meaning: "Start with parameters that control complexity, regularization, or neighborhood size." }],
    tips: model.tips ?? profile?.tips ?? ["Use a Pipeline for preprocessing.", "Compare with a simple baseline.", "Tune on validation data, not the test set."],
    alternatives: model.alternatives ?? profile?.alternatives ?? ["Compare with a compact linear baseline", "Compare with a nonlinear tree baseline"],
    scores: model.scores ?? profile?.scores ?? defaultScores,
    speedTip: model.speedTip ?? profile?.speedTip ?? "Profile before tuning; start with the estimator's main complexity parameter.",
  };
};

