export const modelCatalog: ModelSpec[] = [...coreModels, ...extraModels, ...moreModels].map((model) => ({
  ...model,
  ...modelOverrides[model.id],
}));

export const modelGroups = Array.from(new Set(modelCatalog.map((model) => model.family)));

export const familyProfilesById = familyProfiles;

export function getModelScores(model: ModelSpec): ModelScores {
  return model.scores ?? familyProfiles[model.family]?.scores ?? defaultScores;
}

export function getModelSpeedTip(model: ModelSpec): string {
  return model.speedTip ?? familyProfiles[model.family]?.speedTip ?? "Profile before tuning; start with the estimator's main complexity parameter.";
}

export function averageScores(models: ModelSpec[]): ModelScores {
  if (!models.length) return defaultScores;
  const keys = Object.keys(defaultScores) as (keyof ModelScores)[];
  const result = {} as ModelScores;
  for (const key of keys) {
    const total = models.reduce((sum, model) => sum + getModelScores(model)[key], 0);
    result[key] = Math.round((total / models.length) * 10) / 10;
  }
  return result;
}
